import React, { useState } from 'react';
import styled from 'styled-components';
import { size } from '../device';

const NavBar = styled.nav`
  width: 100%;
  background-color: #0d0d0d;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.9rem 1.5rem;
  position: sticky;
  top: 0;
  z-index: 1000;
`;

const IconButton = styled.button`
  background: none;
  border: none;
  color: white;
  cursor: pointer;
  display: flex;
  align-items: center;
  padding: 0.25rem;
  font-size: 1.4rem;
  line-height: 1;
`;

const LogoLink = styled.a`
  display: flex;
  align-items: center;
  text-decoration: none;
`;

const LogoImg = styled.img`
  height: 22px;
  width: auto;

  @media (max-width: ${size.mobile}) {
    height: 18px;
  }
`;

const MobileMenu = styled.div`
  display: ${({ open }) => (open ? 'flex' : 'none')};
  flex-direction: column;
  position: fixed;
  top: 0;
  left: 0;
  width: 280px;
  height: 100vh;
  background-color: #0d0d0d;
  padding: 4rem 2rem 2rem;
  z-index: 2000;
  gap: 1.5rem;
`;

const Overlay = styled.div`
  display: ${({ open }) => (open ? 'block' : 'none')};
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.6);
  z-index: 1999;
`;

const MenuCloseButton = styled.button`
  background: none;
  border: none;
  color: white;
  cursor: pointer;
  font-size: 1.8rem;
  position: absolute;
  top: 1rem;
  right: 1.5rem;
  line-height: 1;
`;

const MenuLink = styled.a`
  color: white;
  text-decoration: none;
  font-family: 'Open Sans', sans-serif;
  font-size: 1.1rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.15);
  padding-bottom: 1rem;

  &:hover {
    color: #7ecff4;
  }
`;

const Navigation = () => {
  const [menuOpen, setMenuOpen] = useState(false);

  return (
    <>
      <NavBar>
        <IconButton onClick={() => setMenuOpen(true)} aria-label="Open menu">
          ☰
        </IconButton>

        <LogoLink href="https://www.columbiaspectator.com/" target="_blank" rel="noopener noreferrer">
          <LogoImg
            src="/spectator-logo.png"
            alt="Columbia Daily Spectator"
          />
        </LogoLink>

        <IconButton aria-label="Search">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <circle cx="11" cy="11" r="8" />
            <line x1="21" y1="21" x2="16.65" y2="16.65" />
          </svg>
        </IconButton>
      </NavBar>

      <Overlay open={menuOpen} onClick={() => setMenuOpen(false)} />
      <MobileMenu open={menuOpen}>
        <MenuCloseButton onClick={() => setMenuOpen(false)}>×</MenuCloseButton>
        <MenuLink href="#mission" onClick={() => setMenuOpen(false)}>Our Mission</MenuLink>
        <MenuLink href="#goal" onClick={() => setMenuOpen(false)}>Our Goal</MenuLink>
        <MenuLink href="#secure-the-future" onClick={() => setMenuOpen(false)}>Goal 1: Secure the Future</MenuLink>
        <MenuLink href="#invest-in-people" onClick={() => setMenuOpen(false)}>Goal 2: Invest in People</MenuLink>
        <MenuLink href="#faq" onClick={() => setMenuOpen(false)}>FAQ</MenuLink>
      </MobileMenu>
    </>
  );
};

export default Navigation;
